      excludedFromTotal?: boolean
      inputTokens?: number
      outputTokens?: number
      sessions?: number
      sessionCountBasis?: SessionCountBasis
      cacheReadTokens?: number
      /// Add-only: portion of `cost` priced from estimates, from surviving
